match = LOG_PATTERN.match(line)
if not match:
    print(f"DEBUG: Line did not match LOG_PATTERN: {line.strip()}")
    return None

data = match.groupdict()
level = data["level"]
message = data["message"]

parsed_entry: Dict[str, Any] = {
    "timestamp": data["timestamp"],
    "level": level,
    "message": message.strip(),
    "type": level, # Default type for now, refined below
}

if level == "INFO":
    if "User" in message:
        user_match = re.search(r"User (\d+) (.*)", message)
        if user_match:
            parsed_entry["type"] = "USR"
            parsed_entry["user_id"] = user_match.group(1)
            parsed_entry["action"] = user_match.group(2).strip()
        else:
            print(f"DEBUG: INFO User line did not match user_match pattern: {message.strip()}")
    elif "API" in message:
        api_match = re.search(r"API (\S+) took (\d+)ms", message)
        if api_match:
            parsed_entry["type"] = "API"
            parsed_entry["endpoint"] = api_match.group(1)
            parsed_entry["duration_ms"] = int(api_match.group(2))
        else:
            print(f"DEBUG: INFO API line did not match api_match pattern: {message.strip()}")
elif level == "ERROR":
    parsed_entry["type"] = "ERR"
elif level == "WARN":
    parsed_entry["type"] = "WARN"

print(f"DEBUG: Parsed Entry: {parsed_entry}")
return parsed_entry

